sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    var ga = new GlideAjax('TrainingUtils');
    ga.addParam('sysparm_name', 'checkDuplicateSchedule');
    ga.addParam('sysparm_training', g_form.getValue("training"));
    ga.addParam('sysparm_start_date', newValue);
    ga.getXMLAnswer(setMessage);

    //Type appropriate comment here, and begin script below

}

function setMessage(answer) {
    if (answer == 'true') {
		//g_form.addInfoMessage(answer);
		g_form.clearValue("training_date");
		g_form.addErrorMessage("This course is already scheduled for the selected date. Please enter a new date.");

    } else {
        g_form.clearMessages();
		//g_form.addInfoMessage(answer);
    }
}
